                obj = sc_asn1_skip_tag(ctx, &p, &left, entry->tag, &objlen);
                if (obj == NULL) {
                        sc_debug(ctx, SC_LOG_DEBUG_ASN1, "'%s' not present\n", entry->name);
                        if (choice)
